'use strict';

// Every "what day is it" decision in the app must go through here, never
// through a client-supplied timestamp. todayString() computes the calendar
// day in the given IANA timezone (e.g. "America/Los_Angeles"), falling back
// to UTC when no timezone is given or the given one is invalid - that
// fallback is what every call site got for free before per-user timezones
// existed, so omitting the argument is still safe.

const DEFAULT_TIMEZONE = 'UTC';

function now() {
  return new Date();
}

function isValidTimezone(timezone) {
  if (typeof timezone !== 'string' || !timezone) return false;
  try {
    // eslint-disable-next-line no-new
    new Intl.DateTimeFormat('en-US', { timeZone: timezone });
    return true;
  } catch {
    return false;
  }
}

function todayString(timezone = DEFAULT_TIMEZONE, date = now()) {
  const tz = isValidTimezone(timezone) ? timezone : DEFAULT_TIMEZONE;
  const parts = new Intl.DateTimeFormat('en-US', {
    timeZone: tz,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
  }).formatToParts(date);
  const byType = Object.fromEntries(parts.map(({ type, value }) => [type, value]));
  return `${byType.year}-${byType.month}-${byType.day}`;
}

function daysBetween(dateStringA, dateStringB) {
  const a = new Date(`${dateStringA}T00:00:00Z`);
  const b = new Date(`${dateStringB}T00:00:00Z`);
  return Math.round((b - a) / (1000 * 60 * 60 * 24));
}

module.exports = { now, todayString, daysBetween, isValidTimezone, DEFAULT_TIMEZONE };
